create table if not exists pipeline_runs(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id) on delete cascade,status text not null default 'queued',current_step text,progress numeric(5,2) not null default 0,state jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists pipeline_steps(id uuid primary key default gen_random_uuid(),pipeline_run_id uuid not null references pipeline_runs(id) on delete cascade,step text not null,status text not null default 'queued',progress numeric(5,2) not null default 0,checkpoint jsonb not null default '{}',error jsonb,started_at timestamptz,completed_at timestamptz,unique(pipeline_run_id,step));
create table if not exists scenes(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id) on delete cascade,scene_number int not null,status text not null default 'queued',created_at timestamptz not null default now());
create table if not exists scene_versions(id uuid primary key default gen_random_uuid(),scene_id uuid not null references scenes(id) on delete cascade,version int not null,data jsonb not null,created_at timestamptz not null default now(),unique(scene_id,version));
